const quadraticPoint = (
  start: {x: number; y: number},
  control: {x: number; y: number},
  end: {x: number; y: number},
  progress: number,
) => {
  const inverse = 1 - progress;
  return {
    x:
      inverse * inverse * start.x +
      2 * inverse * progress * control.x +
      progress * progress * end.x,
    y:
      inverse * inverse * start.y +
      2 * inverse * progress * control.y +
      progress * progress * end.y,
  };
};

const Background: React.FC<{frame: number}> = ({frame}) => {
  const phase = (frame / REFERENCE_FRAMES) * TAU;
  return (
    <AbsoluteFill
      style={{
        overflow: "hidden",
        background:
          "radial-gradient(circle at 50% 77%, #0a3142 0%, #07192d 19%, #030c1b 51%, #010611 100%)",
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "radial-gradient(ellipse at 50% 42%, rgba(39,231,228,.07) 0%, rgba(3,16,32,.12) 38%, rgba(1,5,14,.72) 82%)",
        }}
      />
      {STARS.map((star, index) => {
        const twinkle =
          0.42 + 0.58 * Math.sin(frame * 0.027 + star.phase) ** 2;
        const y =
          star.y +
          Math.sin(phase + star.phase) * star.drift -
          ((frame * 0.025 * star.drift) % 22);
        return (
          <div
            key={index}
            style={{
              position: "absolute",
              left: star.x,
              top: y,
              width: star.size,
              height: star.size,
              borderRadius: "50%",
              backgroundColor: star.color,
              opacity: star.opacity * twinkle,
              boxShadow:
                star.size > 2
                  ? `0 0 ${4 + star.size * 2}px ${star.color}`
                  : undefined,
            }}
          />
        );
      })}
      <div
        style={{
          position: "absolute",
          left: 235,
          top: 130,
          width: 1450,
          height: 520,
          borderRadius: "50%",
          background:
            "radial-gradient(ellipse, rgba(44,220,224,.06), rgba(16,68,92,.025) 42%, transparent 72%)",
          filter: "blur(22px)",
          opacity: 0.72 + Math.sin(frame * 0.012) * 0.08,
        }}
      />
    </AbsoluteFill>
  );
};

