const DataCell: React.FC<{
  frame: number;
  cell: (typeof MAP_CELLS)[number];
}> = ({frame, cell}) => {
  const local = reveal(frame, 34 + cell.delay, 48);
  if (local <= 0) {
    return null;
  }
  const pulse = 0.62 + 0.38 * Math.sin(frame * 0.032 + cell.phase) ** 2;
  const ambient = reveal(frame, 218, 92);
  const ambientX = Math.sin(frame * 0.012 + cell.phase) * 6 * ambient;
  const ambientY = Math.sin(frame * 0.009 + cell.phase * 1.37) * 4 * ambient;
  const translateX = (960 - cell.x) * (1 - local) * 0.34;
  const translateY = (905 - cell.y) * (1 - local) * 0.48;
  const scale = 0.24 + local * 0.76;
  const opacity = local * cell.opacity * pulse;
  const lineColor = cell.accent;
  return (
    <g
      transform={`translate(${translateX} ${translateY}) translate(${
        cell.x + ambientX
      } ${cell.y + ambientY}) scale(${scale}) translate(${-cell.x} ${-cell.y})`}
      opacity={opacity}
    >
      {cell.kind === 0 ? (
        <>
          <rect
            x={cell.x}
            y={cell.y}
            width={cell.width}
            height={cell.height}
            rx="2"
            fill="#0a2940"
            fillOpacity=".36"
            stroke={lineColor}
            strokeOpacity=".62"
            strokeWidth=".9"
          />
          {range(3).map((line) => (
            <line
              key={line}
              x1={cell.x + 5}
              y1={cell.y + 5 + line * Math.max(4, cell.height / 4)}
              x2={
                cell.x +
                5 +
                (cell.width - 10) *
                  (0.35 + hash01(cell.x + line * 19) * 0.6)
              }
              y2={cell.y + 5 + line * Math.max(4, cell.height / 4)}
              stroke={lineColor}
              strokeOpacity=".72"
              strokeWidth="1.15"
            />
          ))}
        </>
      ) : cell.kind === 1 ? (
        <>
          <line
            x1={cell.x}
            y1={cell.y + cell.height}
            x2={cell.x + cell.width}
            y2={cell.y + cell.height}
            stroke={lineColor}
            strokeOpacity=".65"
          />
          {range(5).map((bar) => {
            const barHeight =
              cell.height * (0.2 + hash01(cell.y + bar * 27) * 0.78);
            return (
              <rect
                key={bar}
                x={cell.x + 2 + bar * (cell.width / 5)}
                y={cell.y + cell.height - barHeight}
                width={Math.max(1.5, cell.width / 8)}
                height={barHeight}
                fill={lineColor}
                fillOpacity={0.48 + bar * 0.09}
              />
            );
          })}
        </>
      ) : cell.kind === 2 ? (
        <>
          {range(8).map((dot) => (
            <circle
              key={dot}
              cx={cell.x + (dot % 4) * (cell.width / 4) + 3}
              cy={cell.y + Math.floor(dot / 4) * (cell.height / 2) + 3}
              r={1.15 + (dot % 3) * 0.35}
              fill={lineColor}
              fillOpacity=".82"
            />
          ))}
          <line
            x1={cell.x + 3}
            y1={cell.y + cell.height - 2}
            x2={cell.x + cell.width - 2}
            y2={cell.y + 2}
            stroke={lineColor}
            strokeOpacity=".36"
          />
        </>
      ) : (
        <>
          <path
            d={`M${cell.x},${cell.y + cell.height * 0.74} L${
              cell.x + cell.width * 0.2
            },${cell.y + cell.height * 0.51} L${
              cell.x + cell.width * 0.42
            },${cell.y + cell.height * 0.67} L${
              cell.x + cell.width * 0.68
            },${cell.y + cell.height * 0.18} L${
              cell.x + cell.width
            },${cell.y + cell.height * 0.4}`}
            fill="none"
            stroke={lineColor}
            strokeWidth="1.35"
            strokeLinejoin="round"
          />
          <circle
            cx={cell.x + cell.width * 0.68}
            cy={cell.y + cell.height * 0.18}
            r="2.2"
            fill={lineColor}
          />
        </>
      )}
    </g>
  );
};

