const ConnectionFan: React.FC<{frame: number}> = ({frame}) => {
  const fan = reveal(frame, 185, 112);
  const start = {x: 960, y: 804};
  return (
    <svg
      width={WIDTH}
      height={HEIGHT}
      viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
      style={{position: "absolute", inset: 0, pointerEvents: "none"}}
    >
      <defs>
        <linearGradient id="beam-gradient" x1="0" y1="1" x2="0" y2="0">
          <stop offset="0" stopColor={C.cyanBright} stopOpacity=".9" />
          <stop offset=".28" stopColor={C.cyan} stopOpacity=".58" />
          <stop offset="1" stopColor={C.cyan} stopOpacity=".04" />
        </linearGradient>
      </defs>
      {FAN_TARGETS.map((target, index) => {
        const localFan = reveal(frame, 185 + (index % 8) * 7, 90);
        const control = {
          x:
            960 +
            (target.x - 960) * 0.2 +
            (hash01(index + 2609) - 0.5) * 170,
          y: 625 - hash01(index + 2711) * 95,
        };
        const path = `M${start.x},${start.y} Q${control.x},${control.y} ${target.x},${target.y}`;
        const packetProgress =
          ((frame * (0.0034 + (index % 5) * 0.00025) +
            hash01(index + 2819)) %
            1 +
            1) %
          1;
        const packet = quadraticPoint(start, control, target, packetProgress);
        const bright = index < REGIONS.length;
        return (
          <g key={index} opacity={fan}>
            <path
              d={path}
              pathLength={1}
              fill="none"
              stroke="url(#beam-gradient)"
              strokeWidth={bright ? 1.9 : 0.95}
              strokeOpacity={bright ? 0.58 : 0.24}
              strokeDasharray={bright ? "0.03 0.018" : "0.02 0.028"}
              strokeDashoffset={1 - localFan - frame * 0.006}
            />
            {localFan > 0.94 ? (
              <>
                <circle
                  cx={packet.x}
                  cy={packet.y}
                  r={bright ? 3.6 : 2.1}
                  fill={bright ? C.cyanBright : C.cyan}
                  opacity={bright ? 0.86 : 0.5}
                />
                {bright ? (
                  <circle
                    cx={packet.x}
                    cy={packet.y}
                    r="8"
                    fill="none"
                    stroke={C.cyan}
                    strokeOpacity=".16"
                  />
                ) : null}
              </>
            ) : null}
          </g>
        );
      })}
      <path
        d="M920 806 Q955 690 960 568 Q965 690 1000 806Z"
        fill={C.cyan}
        fillOpacity={0.09 * fan}
      />
      <rect
        x={938 - Math.sin(frame * 0.03) * 8}
        y="530"
        width={44 + Math.sin(frame * 0.03) * 16}
        height="294"
        fill="url(#core-beam)"
        opacity={fan * 0.54}
      />
      <defs>
        <linearGradient id="core-beam" x1="0" y1="1" x2="0" y2="0">
          <stop offset="0" stopColor={C.white} stopOpacity=".78" />
          <stop offset=".36" stopColor={C.cyan} stopOpacity=".22" />
          <stop offset="1" stopColor={C.cyan} stopOpacity="0" />
        </linearGradient>
      </defs>
    </svg>
  );
};

