const Atmosphere: React.FC<{frame: number}> = ({frame}) => {
  const enter = reveal(frame, 104, 170);
  return (
    <>
      {FLOATING_DUST.map((dust, index) => {
        const x =
          dust.x +
          Math.sin(frame * dust.speed * 0.012 + dust.phase) * 16;
        const y =
          dust.y -
          ((frame * dust.speed + hash01(index + 2909) * 210) % 210);
        const pulse =
          0.35 + 0.65 * Math.sin(frame * 0.018 + dust.phase) ** 2;
        return (
          <div
            key={index}
            style={{
              position: "absolute",
              left: x,
              top: y,
              width: dust.radius * 2,
              height: dust.radius * 2,
              borderRadius: "50%",
              background: index % 19 === 0 ? C.coral : C.cyanBright,
              opacity: dust.opacity * pulse * enter,
              boxShadow:
                dust.radius > 2
                  ? `0 0 9px ${
                      index % 19 === 0 ? C.coral : C.cyanBright
                    }`
                  : undefined,
            }}
          />
        );
      })}
    </>
  );
};

