export const Motion: React.FC = () => {
  const frame = useCurrentFrame();
  const {fps, durationInFrames} = useVideoConfig();
  const normalizedFrame =
    durationInFrames === REFERENCE_FRAMES
      ? frame
      : (frame / Math.max(1, durationInFrames - 1)) * (REFERENCE_FRAMES - 1);
  const safetyOpacity = clamp(normalizedFrame, [0, fps * 0.24], [0, 1]);

  return (
    <AbsoluteFill
      style={{
        width: WIDTH,
        height: HEIGHT,
        overflow: "hidden",
        backgroundColor: C.background,
        color: C.text,
        opacity: safetyOpacity,
      }}
    >
      <Background frame={normalizedFrame} />
      <PerspectiveFloor frame={normalizedFrame} />
      <WorldDataMap frame={normalizedFrame} />
      <ConnectionFan frame={normalizedFrame} />
      <RegionCards frame={normalizedFrame} />
      <Portal frame={normalizedFrame} />
      <Atmosphere frame={normalizedFrame} />
      <Finishing />
      <InterfaceHeader frame={normalizedFrame} />
      <BottomMetrics frame={normalizedFrame} />
    </AbsoluteFill>
  );
};
